sys_variable_value.value:
(function() {
    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Optional Tasks');
    planGr.setValue('employee_id', 'ATF-011');
    planGr.setValue('state', 'active');
    planGr.setValue('readiness_threshold', 80);
    var planId = planGr.insert();

    // 3 mandatory tasks - all complete + verified
    for (var i = 1; i <= 3; i++) {
        var t = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        t.initialize();
        t.setValue('plan', planId);
        t.setValue('task_name', 'Mandatory Task ' + i);
        t.setValue('mandatory', true);
        t.setValue('task_state', 'complete');
        t.setValue('evidence_verified', true);
        t.setValue('department', 'hr');
        t.insert();
    }

    // 1 optional complete
    var opt1 = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    opt1.initialize();
    opt1.setValue('plan', planId);
    opt1.setValue('task_name', 'Optional Complete');
    opt1.setValue('mandatory', false);
    opt1.setValue('task_state', 'complete');
    opt1.setValue('evidence_verified', true);
    opt1.setValue('department', 'facilities');
    opt1.insert();

    // 1 optional incomplete
    var opt2 = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    opt2.initialize();
    opt2.setValue('plan', planId);
    opt2.setValue('task_name', 'Optional Incomplete');
    opt2.setValue('mandatory', false);
    opt2.setValue('task_state', 'open');
    opt2.setValue('evidence_verified', false);
    opt2.setValue('department', 'finance');
    opt2.insert();

    var engine = new DayOneReadinessEngine(planId);
    var score = engine.calculateScore();
    // 4 verified out of 5 applicable = 80%
    if (score !== 80) throw new Error('Score should be 80, got ' + score);

    var gate = new DayOneGateValidator(planId);
    var result = gate.validateGate();
    if (!result.passed) throw new Error('Gate should pass (score 80 >= threshold 80, all mandatory done) but failed: ' + result.reasons.join('; '));
    gs.info('T-11 PASSED: Optional incomplete tasks do not block readiness');
})();
